<?php
namespace App\Http\Controllers\Sso;
use App\Application\Sso\CentralLoginUrl;use App\Application\Sso\PermissionService;use App\Application\Sso\SsoTokenValidator;use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Log;use Illuminate\Support\Str;use RuntimeException;
class SsoLoginController extends Controller { public function __invoke(Request $request,SsoTokenValidator $validator,PermissionService $permissions,CentralLoginUrl $central){$token=(string)$request->query('token','');if($token==='')return redirect()->away($central->loginUrl());try{$claims=$validator->validate($token);$userId=$validator->userId($claims);$map=$permissions->fetch($userId,(string)config('gpha_sso.module_id'));if(!collect($map)->contains(fn($v)=>is_array($v)&&$v!==[]))return response()->view('errors.sso-access',['title'=>'EMS access has not been assigned','message'=>'Your Central Login account has no permissions assigned for EMS.'],403);}catch(RuntimeException $e){Log::warning('EMS SSO sign-in failed',['reason'=>$e->getMessage(),'token_fingerprint'=>substr(hash('sha256',$token),0,12)]);return response()->view('errors.sso-access',['title'=>'Central Login sign-in failed','message'=>$e->getMessage()],str_contains(strtolower($e->getMessage()),'permission')?503:401);}$username=(string)($claims['username']??$claims['unique_name']??$userId);$name=(string)($claims['Staff Name']??$claims['fullname']??$username);$email=$this->email($claims,$userId);$user=DB::transaction(fn()=>User::updateOrCreate(['sso_user_id'=>$userId],['sso_username'=>$username,'name'=>$name,'email'=>$email,'password'=>bcrypt(Str::random(48)),'sso_claims'=>$claims,'branch_ids'=>array_values((array)($claims['branch_id']??[])),'branch_codes'=>array_values((array)($claims['branch_code']??[])),'branch_names'=>array_values((array)($claims['branch_name']??[]))]));auth()->login($user);$request->session()->regenerate();$request->session()->put(['sso.module_id'=>config('gpha_sso.module_id'),'sso.permissions'=>$map,'sso.permissions_synced_at'=>now()->timestamp,'sso.branches'=>['ids'=>$user->branch_ids??[],'codes'=>$user->branch_codes??[],'names'=>$user->branch_names??[]],'sso.active_branch_code'=>($user->branch_codes??[])[0]??null]);return redirect()->route('dashboard');} private function email(array $c,string $id):string{foreach(['email','Email','emailaddress','mail'] as $key)if(filter_var($c[$key]??null,FILTER_VALIDATE_EMAIL))return$c[$key];return$id.'@sso.gpha.local';} }
